class Sessions:
    def __init__(self, credentials, settings, clock):
        self.credentials = credentials
        self.settings = settings
        self.clock = clock
        self.rows = OrderedDict()

    def prune(self):
        now = self.clock.now()
        for sid, session in list(self.rows.items()):
            if session.expires <= now:
                del self.rows[sid]

