            raise Invalid('catalog registration')

    def list_tools(self):
        return {'tools': deepcopy(self.catalog)}

    def describe(self, tool):
        for item in self.catalog:
            if item['name'] == tool:
                return deepcopy(item)
        from .errors import Missing
